  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10","C15","C24","C03","C13","C01","C04","C26","C25","C41"],
  "claims": [
    {
      "claim": "Cladribine, the closest 2-halogenated deoxyadenosine analog, had absolute oral bioavailability of 36-46% in fasted patients (C10, C15, C24); L5 shows it is a BCRP substrate (C155, C159, C176, C190, C151, C153), yet its measured F remains well above 20%, so gut-wall efflux in this class does not imply F < 20%.",
      "card_ids": ["C10","C15","C24","C155","C159","C176","C190","C151","C153"]
    },
    {
      "claim": "Didanosine, a polar purine nucleoside with low PAMPA permeability and probenecid-sensitive secretory transport, had fasted F of 22-28% (C03, C13, C121, C165), still above the threshold.",
      "card_ids": ["C03","C13","C121","C165"]
    },
    {
      "claim": "EFdA, the closest 2-fluoroadenine nucleoside in L5, showed measurable Caco-2 A-to-B permeability of about 4.8-6.0 x 10^-7 cm/s with pH-independent transport (C193, C196), providing no affirmative efflux or intestinal-metabolism barrier for the 2-fluoroadenine core.",
      "card_ids": ["C193","C196"]
    },
    {
      "claim": "Other polar nucleosides (lamivudine, emtricitabine, zalcitabine) had fasted F of 69-95%, 92%, and 30-80%, respectively (C01, C04, C26, C25, C41), supporting that low passive permeability does not translate to F < 20%.",
      "card_ids": ["C01","C04","C26","C25","C41"]
    },
    {
      "claim": "L5 records show nucleoside transporters (ENT1/2, CNT3) mediate intestinal uptake of nucleoside analogs including cladribine, ribavirin, NHC, and GS-441524 (C177, C181, C187, C154, C163, C164), providing a plausible absorptive route for the query despite low passive permeability.",
      "card_ids": ["C177","C181","C187","C154","C163","C164"]
    },
    {
      "claim": "The high efflux ratio reported for GS-441524 (C172) is structurally distant (pyrrolotriazine C-nucleoside) and lacks an F value; it is not affirmative threshold-relevant evidence for the query.",
      "card_ids": ["C172"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C193","C196","C155","C159","C176","C190","C151","C153","C169","C165","C184","C177","C181","C187"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability or IV-comparator exposure measurement exists for the query molecule.",
    "No direct gut-wall efflux or intestinal metabolism measurement exists for the query; L5 records are for analogs (EFdA, cladribine, didanosine, GS-441524).",
    "The query's pyranose sugar differs from the furanose/oxathiolane sugars of the supporting analogs, limiting structural transferability.",
    "No human PK data exist for the query; some supporting F values are from mice or different patient populations.",
    "GS-441524's high efflux ratio is structurally distant and lacks an F value, so it cannot serve as affirmative low evidence."
  ],
  "decision_summary": "Prediction remains high (F >= 20%): direct F values for close nucleoside analogs (cladribine 36-46%, didanosine 22-28%, lamivudine 69-95%, emtricitabine 92%, zalcitabine 30-80%) all exceed the threshold. L5 gut-wall efflux/intestinal metabolism evidence shows BCRP efflux in cladribine and secretory transport in didanosine without reducing F below 20%, and the closest 2-fluoroadenine analog EFdA shows measurable pH-independent Caco-2 permeability; no affirmative threshold-relevant low evidence was added. Confidence remains moderate due to lack of direct query measurements and the sugar-ring difference."
}

